<?php
require_once dirname(__DIR__).'/config/config.php';
if(!is_admin()){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='delete_book'){$id=(int)($_POST['book_id']??0);$s=$pdo->prepare("DELETE FROM books WHERE id=?");$s->execute([$id]);set_flash('Book deleted.');}
 if($action==='update_order'){$id=(int)($_POST['order_id']??0);$status=$_POST['status']??'Placed';$allowed=['Placed','Processing','Shipped','Out for delivery','Delivered','Cancelled'];if(in_array($status,$allowed,true)){$pdo->beginTransaction();$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$status,$id]);$t=$pdo->prepare("INSERT INTO order_tracking(order_id,status,note) VALUES(?,?,?)");$t->execute([$id,$status,'Order status updated by store admin.']);$pdo->commit();set_flash('Order status updated.');}}
 header('Location: dashboard.php#orders');exit;
}
$counts=['books'=>(int)$pdo->query("SELECT COUNT(*) FROM books")->fetchColumn(),'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM orders")->fetchColumn(),'sales'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status <> 'Cancelled'")->fetchColumn()];
$books=$pdo->query("SELECT b.*,c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id ORDER BY b.id DESC")->fetchAll();
$orders=$pdo->query("SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 30")->fetchAll();
$pageTitle='Admin dashboard — OnlineBookStore';include dirname(__DIR__).'/includes/header.php';
?>
<main class="container section admin-page"><div class="admin-heading"><div><span class="eyebrow">STORE CONTROL ROOM</span><h1>Admin <span class="gradient-text">dashboard.</span></h1><p>Welcome, <?= e($_SESSION['admin_name']??'admin') ?>.</p></div><a class="btn btn-outline" href="logout.php">Admin logout</a></div>
<div class="admin-stats"><div class="stat-card"><span>Books</span><strong><?= $counts['books'] ?></strong></div><div class="stat-card"><span>Customers</span><strong><?= $counts['users'] ?></strong></div><div class="stat-card"><span>Orders</span><strong><?= $counts['orders'] ?></strong></div><div class="stat-card"><span>Order value</span><strong><?= money($counts['sales']) ?></strong></div></div>
<div class="admin-toolbar"><h2>Book inventory</h2><a class="btn btn-primary" href="book-form.php">+ Add new book</a></div>
<div class="table-wrap"><table class="admin-table"><thead><tr><th>Book</th><th>Category</th><th>Price</th><th>Stock</th><th>Featured</th><th>Actions</th></tr></thead><tbody><?php foreach($books as $b): ?><tr><td><div class="admin-book"><img src="<?= e($b['cover']?:'../assets/img/book-placeholder.svg') ?>" alt=""><div><strong><?= e($b['title']) ?></strong><small><?= e($b['author']) ?></small></div></div></td><td><?= e($b['category_name']??'—') ?></td><td><?= money($b['price']) ?></td><td><?= (int)$b['stock'] ?></td><td><?= $b['is_featured']?'Yes':'No' ?></td><td class="action-cell"><a href="book-form.php?id=<?= (int)$b['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Delete this book?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_book"><input type="hidden" name="book_id" value="<?= (int)$b['id'] ?>"><button class="table-delete">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<div id="orders" class="admin-toolbar"><h2>Recent orders</h2><span class="muted">Latest 30 orders</span></div>
<div class="table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= e($o['order_number']) ?></strong><small><?= e(date('d M Y',strtotime($o['created_at']))) ?></small></td><td><?= e($o['customer']) ?></td><td><?= money($o['total']) ?></td><td><?= e($o['payment_method']) ?><small><?= e($o['payment_status']) ?></small></td><td><?= e($o['status']) ?></td><td><form method="post" class="status-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_order"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(['Placed','Processing','Shipped','Out for delivery','Delivered','Cancelled'] as $st): ?><option <?= $o['status']===$st?'selected':'' ?>><?= e($st) ?></option><?php endforeach; ?></select><button>Save</button></form></td></tr><?php endforeach; ?></tbody></table></div>
</main>
<?php include dirname(__DIR__).'/includes/footer.php'; ?>
